#include <iostream>
using namespace std;

// Function to check if a number is prime using recursion
bool isPrime(int n, int divisor = 2) {
    // Base cases
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % divisor == 0) return false;
    if (divisor * divisor > n) return true;
    // Recursive case
    return isPrime(n, divisor + 1);
}

// Function to reverse the array using recursion
void reverseArray(int arr[], int start, int end) {
    // Base case: when start >= end, no more swaps needed
    if (start >= end) return;
    // Swap the elements at start and end
    int temp = arr[start];
    arr[start] = arr[end];
    arr[end] = temp;
    // Recursive call to reverse the remaining elements
    reverseArray(arr, start + 1, end - 1);
}

